WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM seq WHERE n < 10) SELECT n FROM seq;
WITH RECURSIVE evens(n) AS (SELECT 0 UNION ALL SELECT n + 2 FROM evens WHERE n < 8) SELECT n FROM evens ORDER BY n;
WITH RECURSIVE countdown(n) AS (SELECT 10 UNION ALL SELECT n - 1 FROM countdown WHERE n > 0) SELECT n FROM countdown;
WITH RECURSIVE signed(n) AS (SELECT -3 UNION ALL SELECT n + 1 FROM signed WHERE n < 3) SELECT n FROM signed;
WITH RECURSIVE powers(n) AS (SELECT 1 UNION ALL SELECT n * 2 FROM powers WHERE n < 64) SELECT n FROM powers;
WITH RECURSIVE fib(step, a, b) AS (SELECT 0, 0, 1 UNION ALL SELECT step + 1, b, a + b FROM fib WHERE step < 10) SELECT step, a, b FROM fib;
WITH RECURSIVE factorial(n, product) AS (SELECT 1, 1 UNION ALL SELECT n + 1, product * (n + 1) FROM factorial WHERE n < 6) SELECT n, product FROM factorial;
WITH RECURSIVE squares(n, total) AS (SELECT 0, 0 UNION ALL SELECT n + 1, total + (n + 1) * (n + 1) FROM squares WHERE n < 5) SELECT n, total FROM squares;
WITH RECURSIVE labels(n, label) AS (SELECT 1, 'batch' UNION ALL SELECT n + 1, label FROM labels WHERE n < 4) SELECT n, label FROM labels;
WITH RECURSIVE toggles(n, enabled) AS (SELECT 0, TRUE UNION ALL SELECT n + 1, NOT enabled FROM toggles WHERE n < 5) SELECT n, enabled FROM toggles;
WITH RECURSIVE bounded(n, stop) AS (SELECT 2, 7 UNION ALL SELECT n + 1, stop FROM bounded WHERE n < stop) SELECT n FROM bounded;
WITH RECURSIVE ages(n) AS (SELECT age FROM users WHERE id = 1 UNION ALL SELECT n + 1 FROM ages WHERE n < 27) SELECT n FROM ages;
WITH RECURSIVE retries(user_id, attempt) AS (SELECT id, 1 FROM users UNION ALL SELECT user_id, attempt + 1 FROM retries WHERE attempt < 3) SELECT user_id, attempt FROM retries ORDER BY user_id, attempt;
WITH RECURSIVE installments(order_id, balance) AS (SELECT id, amount FROM orders UNION ALL SELECT order_id, balance - 50 FROM installments WHERE balance > 50) SELECT order_id, balance FROM installments;
WITH RECURSIVE once(n) AS (SELECT 42 UNION ALL SELECT n + 1 FROM once WHERE FALSE) SELECT n FROM once;
WITH RECURSIVE unique_steps(n) AS (SELECT 1 UNION SELECT n + 1 FROM unique_steps WHERE n < 5) SELECT n FROM unique_steps;
WITH RECURSIVE bits(enabled) AS (SELECT TRUE UNION SELECT NOT enabled FROM bits) SELECT enabled FROM bits;
WITH RECURSIVE signs(n) AS (SELECT 1 UNION SELECT -n FROM signs) SELECT n FROM signs;
WITH RECURSIVE page(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM page WHERE n < 20) SELECT n AS sequence_number FROM page ORDER BY sequence_number DESC LIMIT 4 OFFSET 2;
WITH RECURSIVE "number series"("current value") AS (SELECT 0 UNION ALL SELECT "current value" + 1 FROM "number series" WHERE "current value" < 3) SELECT "current value" FROM "number series";
WITH RECURSIVE hierarchy(id, manager_id, depth) AS (SELECT id, manager_id, 0 FROM employees WHERE manager_id = 99 UNION ALL SELECT e.id, e.manager_id, h.depth + 1 FROM hierarchy h JOIN employees e ON e.manager_id = h.id) SELECT id, manager_id, depth FROM hierarchy;
WITH RECURSIVE ancestors(id, manager_id, level) AS (SELECT id, manager_id, 0 FROM employees WHERE id = 2 UNION ALL SELECT e.id, e.manager_id, a.level + 1 FROM ancestors a JOIN employees e ON e.id = a.manager_id) SELECT id, manager_id, level FROM ancestors;
WITH RECURSIVE team(id, name, depth) AS (SELECT id, name, 0 FROM employees WHERE id = 1 UNION ALL SELECT e.id, e.name, t.depth + 1 FROM team t JOIN employees e ON e.manager_id = t.id) SELECT name, depth FROM team ORDER BY depth, name;
WITH RECURSIVE high_paid(id) AS (SELECT id FROM employees WHERE id = 1 UNION ALL SELECT e.id FROM high_paid h JOIN employees e ON e.manager_id = h.id WHERE e.salary >= 85) SELECT id FROM high_paid;
WITH RECURSIVE same_department(id, department_id) AS (SELECT id, department_id FROM employees WHERE id = 1 UNION ALL SELECT e.id, e.department_id FROM same_department s JOIN employees e ON e.manager_id = s.id AND e.department_id = s.department_id) SELECT id, department_id FROM same_department;
WITH RECURSIVE department_tree(id) AS (SELECT id FROM employees WHERE department_id = 1 UNION ALL SELECT e.id FROM department_tree t JOIN employees e ON e.manager_id = t.id) SELECT DISTINCT id FROM department_tree;
WITH RECURSIVE descendants(root_id, id) AS (SELECT id, id FROM employees UNION ALL SELECT d.root_id, e.id FROM descendants d JOIN employees e ON e.manager_id = d.id) SELECT root_id, id FROM descendants ORDER BY root_id, id;
WITH RECURSIVE salary_paths(id, total) AS (SELECT id, salary FROM employees WHERE id = 1 UNION ALL SELECT e.id, p.total + e.salary FROM salary_paths p JOIN employees e ON e.manager_id = p.id) SELECT id, total FROM salary_paths;
WITH RECURSIVE chain(id, manager_id, depth) AS (SELECT id, manager_id, 0 FROM employees WHERE id = 3 UNION ALL SELECT e.id, e.manager_id, c.depth + 1 FROM chain c JOIN employees e ON e.id = c.manager_id WHERE c.depth < 4) SELECT id, depth FROM chain;
WITH RECURSIVE levels(id, depth) AS (SELECT id, 0 FROM employees WHERE manager_id = 99 UNION ALL SELECT e.id, l.depth + 1 FROM levels l JOIN employees e ON e.manager_id = l.id) SELECT depth, COUNT(*) AS people FROM levels GROUP BY depth ORDER BY depth;
WITH RECURSIVE depth_scan(id, depth) AS (SELECT id, 0 FROM employees WHERE id = 1 UNION ALL SELECT e.id, d.depth + 1 FROM depth_scan d JOIN employees e ON e.manager_id = d.id) SELECT MAX(depth) AS maximum_depth FROM depth_scan;
WITH RECURSIVE staff(id, department_id, name) AS (SELECT id, department_id, name FROM employees WHERE id = 1 UNION ALL SELECT e.id, e.department_id, e.name FROM staff s JOIN employees e ON e.manager_id = s.id) SELECT s.name, d.name FROM staff s JOIN departments d ON d.id = s.department_id;
WITH RECURSIVE all_staff(id, department_id, name) AS (SELECT id, department_id, name FROM employees WHERE manager_id = 99 UNION ALL SELECT e.id, e.department_id, e.name FROM all_staff s JOIN employees e ON e.manager_id = s.id) SELECT s.name, d.name FROM all_staff s LEFT JOIN departments d ON d.id = s.department_id;
WITH RECURSIVE reports(id) AS (SELECT id FROM employees WHERE id = 1 UNION ALL SELECT e.id FROM employees e JOIN reports r ON e.manager_id = r.id) SELECT id FROM reports;
WITH RECURSIVE cross_reports(id) AS (SELECT id FROM employees WHERE id = 1 UNION ALL SELECT e.id FROM cross_reports r CROSS JOIN employees e WHERE e.manager_id = r.id) SELECT id FROM cross_reports;
WITH RECURSIVE reachable(node) AS (SELECT target FROM edges WHERE source = 1 UNION SELECT e.target FROM reachable r JOIN edges e ON e.source = r.node) SELECT node FROM reachable ORDER BY node;
WITH RECURSIVE closure(node) AS (SELECT 1 UNION SELECT e.target FROM closure c JOIN edges e ON e.source = c.node) SELECT node FROM closure ORDER BY node;
WITH RECURSIVE paths(root, node) AS (SELECT source, target FROM edges UNION SELECT p.root, e.target FROM paths p JOIN edges e ON e.source = p.node) SELECT root, node FROM paths ORDER BY root, node;
WITH RECURSIVE reverse_reachable(node) AS (SELECT 4 UNION SELECT e.source FROM reverse_reachable r JOIN edges e ON e.target = r.node) SELECT node FROM reverse_reachable;
WITH RECURSIVE isolated(node) AS (SELECT 404 UNION SELECT e.target FROM isolated i JOIN edges e ON e.source = i.node) SELECT node FROM isolated;
WITH RECURSIVE components(part_id, quantity) AS (SELECT child_id, quantity FROM parts WHERE parent_id = 1 UNION ALL SELECT p.child_id, c.quantity * p.quantity FROM components c JOIN parts p ON p.parent_id = c.part_id) SELECT part_id, quantity FROM components;
WITH RECURSIVE assembly(part_id, quantity, depth) AS (SELECT child_id, quantity, 1 FROM parts WHERE parent_id = 1 UNION ALL SELECT p.child_id, a.quantity * p.quantity, a.depth + 1 FROM assembly a JOIN parts p ON p.parent_id = a.part_id) SELECT part_id, quantity, depth FROM assembly ORDER BY depth, part_id;
WITH RECURSIVE requirements(part_id, quantity) AS (SELECT child_id, quantity FROM parts WHERE parent_id = 1 UNION ALL SELECT p.child_id, r.quantity * p.quantity FROM requirements r JOIN parts p ON p.parent_id = r.part_id) SELECT part_id, SUM(quantity) AS total_quantity FROM requirements GROUP BY part_id ORDER BY part_id;
WITH RECURSIVE component_rows(part_id) AS (SELECT child_id FROM parts WHERE parent_id = 1 UNION ALL SELECT p.child_id FROM component_rows c JOIN parts p ON p.parent_id = c.part_id) SELECT COUNT(*) AS component_count FROM component_rows;
WITH RECURSIVE leaf_parts(part_id, quantity) AS (SELECT child_id, quantity FROM parts WHERE parent_id = 1 UNION ALL SELECT p.child_id, l.quantity * p.quantity FROM leaf_parts l JOIN parts p ON p.parent_id = l.part_id) SELECT l.part_id, l.quantity FROM leaf_parts l LEFT JOIN parts p ON p.parent_id = l.part_id WHERE p.child_id IS NULL;
WITH RECURSIVE roots(id) AS (SELECT id FROM employees WHERE id = 1), traversal(id) AS (SELECT id FROM roots UNION ALL SELECT e.id FROM traversal t JOIN employees e ON e.manager_id = t.id) SELECT id FROM traversal;
WITH RECURSIVE numbers(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM numbers WHERE n < 5), doubled(value) AS (SELECT n * 2 FROM numbers) SELECT value FROM doubled;
WITH RECURSIVE left_seq(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM left_seq WHERE n < 3), right_seq(n) AS (SELECT 4 UNION ALL SELECT n + 1 FROM right_seq WHERE n < 6) SELECT l.n, r.n FROM left_seq l CROSS JOIN right_seq r;
SELECT q.n FROM (WITH RECURSIVE nested(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM nested WHERE n < 4) SELECT n FROM nested) AS q;
WITH RECURSIVE inferred AS (SELECT 1 AS n UNION ALL SELECT n + 1 FROM inferred WHERE n < 5) SELECT n FROM inferred;
